import { UserApi } from '../api/userApi';
import { ChangeTeamRequest } from '../model';
const userApi = new UserApi();
userApi.setApiKey("YOUR_API_KEY");
var changeTeam = new ChangeTeamRequest();
changeTeam.toTeamId = "TEAM_ID";
async function UserChangeteam() {
    try {
        await userApi.changeTeam("USER_ID",changeTeam);
        console.log("user changed the team");
    } catch (error:any) {
        console.error("Error occurred while calling the API:", error.message);
    }
}
UserChangeteam();
